solution:
def solve(nums, target):
    left, right = 0, len(nums) - 1
    while left < right:
        s = nums[left] + nums[right]
        if s == target:
            return f"{left + 1} {right + 1}"
        elif s < target:
            left += 1
        else:
            right -= 1
    return ""

